tool_schemas.implementation:
def get_profiles(account_id, email=None, phone=None, external_id=None, status=None, created_at_gte=None, created_at_lte=None, updated_at_gte=None, updated_at_lte=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string"))
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time"))
    def _dt_from_row(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # ---- Auth (ambient): pick an active account that matches requested account_id ----
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    used_account_id = account_id if acct else None

    # ---- request logging / quotas ----
    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    endpoint = "get_profiles"
    # Simple per-account rate limit (observable): 120 requests/minute; daily quota 50k.
    def _recent_count(seconds):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if used_account_id is not None and r.get("account_id") != used_account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= cutoff:
                c += 1
        return c
    def _today_count():
        utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        start = utc.replace(hour=0, minute=0, second=0, microsecond=0)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if used_account_id is not None and r.get("account_id") != used_account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= start:
                c += 1
        return c

    # Validate required params/types first
    if not isinstance(account_id, str) or not account_id:
        # log
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id if isinstance(account_id, str) else None, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "account_id is required and must be a string")
    if acct is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No active account context can serve this request")

    # Quota checks
    if _recent_count(60) >= 120:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _today_count() >= 50000:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "QUOTA_EXCEEDED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Validate optional filters
    if email is not None and not isinstance(email, str):
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "email must be a string")
    if phone is not None and not isinstance(phone, str):
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "phone must be a string")
    if external_id is not None and not isinstance(external_id, str):
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "external_id must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in ["active", "suppressed", "deletion_requested", "deleted"]:
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "status must be one of active, suppressed, deletion_requested, deleted")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ["created_at", "-created_at", "updated_at", "-updated_at"]:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "sort must be one of created_at, -created_at, updated_at, -updated_at")

    ca_g = _parse_dt(created_at_gte, "created_at_gte")
    if isinstance(ca_g, tuple) and ca_g and ca_g[0] == "__bad__":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return ca_g[1]
    ca_l = _parse_dt(created_at_lte, "created_at_lte")
    if isinstance(ca_l, tuple) and ca_l and ca_l[0] == "__bad__":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return ca_l[1]
    ua_g = _parse_dt(updated_at_gte, "updated_at_gte")
    if isinstance(ua_g, tuple) and ua_g and ua_g[0] == "__bad__":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return ua_g[1]
    ua_l = _parse_dt(updated_at_lte, "updated_at_lte")
    if isinstance(ua_l, tuple) and ua_l and ua_l[0] == "__bad__":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return ua_l[1]

    # Cursor handling: base64-encoded JSON {"o": offset, "s": sort, "f": <fingerprint>}
    def _fingerprint():
        return {
            "account_id": used_account_id,
            "email": email, "phone": phone, "external_id": external_id, "status": status,
            "created_at_gte": created_at_gte, "created_at_lte": created_at_lte,
            "updated_at_gte": updated_at_gte, "updated_at_lte": updated_at_lte,
            "sort": sort
        }
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "o" not in obj or "s" not in obj or "f" not in obj:
                raise ValueError("bad cursor")
            if obj.get("s") != sort or obj.get("f") != _fingerprint():
                request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
                _save("request_logs.json", request_logs)
                return _err("VALIDATION_ERROR", "cursor does not match requested filters/sort")
            offset = obj.get("o")
            if not isinstance(offset, int) or offset < 0:
                raise ValueError("bad offset")
        except Exception:
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    rows = [p for p in profiles if p.get("account_id") == used_account_id]

    # Default: exclude deleted unless explicitly filtering to deleted
    if status is None:
        rows = [p for p in rows if p.get("status") != "deleted"]
    else:
        rows = [p for p in rows if p.get("status") == status]

    if email is not None:
        rows = [p for p in rows if p.get("email") == email]
    if phone is not None:
        rows = [p for p in rows if p.get("phone") == phone]
    if external_id is not None:
        rows = [p for p in rows if p.get("external_id") == external_id]

    def _in_range(p):
        cdt = _dt_from_row(p.get("created_at"))
        udt = _dt_from_row(p.get("updated_at"))
        if ca_g is not None and (cdt is None or cdt < ca_g):
            return False
        if ca_l is not None and (cdt is None or cdt > ca_l):
            return False
        if ua_g is not None and (udt is None or udt < ua_g):
            return False
        if ua_l is not None and (udt is None or udt > ua_l):
            return False
        return True
    rows = [p for p in rows if _in_range(p)]

    reverse = sort.startswith("-")
    key = sort[1:] if reverse else sort

    def _key(p):
        dt = _dt_from_row(p.get(key))
        # Stable ordering tie-breaker by id
        return (dt is None, dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), p.get("id") or "")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        obj = {"o": next_offset, "s": sort, "f": _fingerprint()}
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

    request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": used_account_id, "status": "ok", "error_code": None, "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
    _save("request_logs.json", request_logs)
    return resp

def get_profile(profile_id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "get_profile"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _dt_from_row(v):
        if v is None or not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Validate
    if not isinstance(profile_id, str) or not profile_id:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": None, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "profile_id is required and must be a string")

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []
    prof = next((p for p in profiles if p.get("id") == profile_id), None)
    if prof is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": None, "status": "error", "error_code": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Profile not found")

    # Ambient auth: any active account may read its own profile; ensure the owning account is active.
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == prof.get("account_id") and a.get("status") == "active"), None)
    if acct is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": prof.get("account_id"), "status": "error", "error_code": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Not allowed to read this profile")

    # Rate/Quota similar to list: 240/min, 100k/day for this endpoint (per account)
    def _recent_count(seconds):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != acct.get("id"):
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= cutoff:
                c += 1
        return c
    def _today_count():
        utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        start = utc.replace(hour=0, minute=0, second=0, microsecond=0)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != acct.get("id"):
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= start:
                c += 1
        return c

    if _recent_count(60) >= 240:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": acct.get("id"), "status": "error", "error_code": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _today_count() >= 100000:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": acct.get("id"), "status": "error", "error_code": "QUOTA_EXCEEDED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": acct.get("id"), "status": "ok", "error_code": None, "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
    _save("request_logs.json", request_logs)
    return {"data": prof}

def create_profile(account_id, email=None, phone=None, external_id=None, first_name=None, last_name=None, location=None, properties=None, consent=None, status=None, **_extra):
    import json, os, datetime, time, secrets, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "create_profile"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _dt_from_row(v):
        if v is None or not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    # Auth: require account exists and active
    if not isinstance(account_id, str) or not account_id:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id if isinstance(account_id, str) else None, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "account_id is required and must be a string")
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Account is not active")

    # Rate/Quota: mutations stricter
    def _recent_count(seconds):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= cutoff:
                c += 1
        return c
    def _today_count():
        utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        start = utc.replace(hour=0, minute=0, second=0, microsecond=0)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= start:
                c += 1
        return c
    if _recent_count(60) >= 60:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _today_count() >= 20000:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "QUOTA_EXCEEDED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Validate fields/types
    for fld, val in [("email", email), ("phone", phone), ("external_id", external_id), ("first_name", first_name), ("last_name", last_name)]:
        if val is not None and not isinstance(val, str):
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", f"{fld} must be a string")
    for fld, val in [("location", location), ("properties", properties), ("consent", consent)]:
        if val is not None and not isinstance(val, dict):
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", f"{fld} must be an object")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ["active", "suppressed", "deletion_requested", "deleted"]:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "status must be one of active, suppressed, deletion_requested, deleted")

    # Business rule: require at least one identifier
    if (email is None or email == "") and (phone is None or phone == "") and (external_id is None or external_id == ""):
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "At least one of email, phone, external_id must be provided")

    # Constraint: for active/suppressed must have at least one identifier (already enforced)
    if status in ["active", "suppressed"] and (email is None and phone is None and external_id is None):
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Active/suppressed profiles must have at least one identifier")

    # If creating as deleted, must set deleted_at (schema says non-null iff deleted)
    deleted_at = None
    if status == "deleted":
        deleted_at = now

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    # Uniqueness per account where not null (all statuses; schema constraint)
    def _collision(field, value):
        if value is None:
            return None
        for p in profiles:
            if p.get("account_id") != account_id:
                continue
            if p.get(field) == value:
                return p
        return None

    for field, value in [("email", email), ("phone", phone), ("external_id", external_id)]:
        if value is not None:
            c = _collision(field, value)
            if c is not None:
                request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "CONFLICT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
                _save("request_logs.json", request_logs)
                return _err("CONFLICT", f"{field} already exists for another profile in this account", existing_profile_id=c.get("id"))

    def _new_id(prefix):
        alphabet = string.ascii_lowercase + string.digits
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    new_profile = {
        "id": _new_id("klv_prof_"),
        "account_id": account_id,
        "email": email,
        "phone": phone,
        "external_id": external_id,
        "first_name": first_name,
        "last_name": last_name,
        "location": location,
        "properties": properties,
        "consent": consent,
        "status": status,
        "deleted_at": deleted_at,
        "created_at": now,
        "updated_at": now
    }

    profiles.append(new_profile)
    _save("profiles.json", profiles)

    request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "ok", "error_code": None, "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
    _save("request_logs.json", request_logs)
    return {"data": new_profile}

def update_profile(profile_id, email=None, phone=None, external_id=None, first_name=None, last_name=None, location=None, properties=None, consent=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "update_profile"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _dt_from_row(v):
        if v is None or not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    if not isinstance(profile_id, str) or not profile_id:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": None, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "profile_id is required and must be a string")

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    idx = None
    for i, p in enumerate(profiles):
        if p.get("id") == profile_id:
            idx = i
            break
    if idx is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": None, "status": "error", "error_code": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Profile not found")

    prof = profiles[idx]
    account_id = prof.get("account_id")

    # Ambient auth: account owning profile must be active
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") == "active"), None)
    if acct is None:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Account is not active")

    # Rate/Quota for updates
    def _recent_count(seconds):
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= cutoff:
                c += 1
        return c
    def _today_count():
        utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        start = utc.replace(hour=0, minute=0, second=0, microsecond=0)
        c = 0
        for r in request_logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _dt_from_row(r.get("timestamp"))
            if ts and ts >= start:
                c += 1
        return c
    if _recent_count(60) >= 120:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "RATE_LIMIT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _today_count() >= 30000:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "QUOTA_EXCEEDED", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Reject updates to deleted profiles
    if prof.get("status") == "deleted":
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "INVALID_TRANSITION", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("INVALID_TRANSITION", "Cannot update a deleted profile")

    # Validate field types
    for fld, val in [("email", email), ("phone", phone), ("external_id", external_id), ("first_name", first_name), ("last_name", last_name)]:
        if val is not None and not isinstance(val, str):
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", f"{fld} must be a string")
    for fld, val in [("location", location), ("properties", properties), ("consent", consent)]:
        if val is not None and not isinstance(val, dict):
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", f"{fld} must be an object")

    if status is not None:
        if not isinstance(status, str) or status not in ["active", "suppressed", "deletion_requested", "deleted"]:
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "status must be one of active, suppressed, deletion_requested, deleted")
        # lifecycle transitions (profiles)
        transitions = {
            "active": ["suppressed", "deletion_requested", "deleted"],
            "suppressed": ["active", "deletion_requested", "deleted"],
            "deletion_requested": ["deleted"],
            "deleted": []
        }
        cur = prof.get("status")
        if status != cur:
            allowed = transitions.get(cur, [])
            if status not in allowed:
                request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "INVALID_TRANSITION", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
                _save("request_logs.json", request_logs)
                return _err("INVALID_TRANSITION", f"Cannot transition profile status from {cur} to {status}")

    # Uniqueness checks if identifier is changing (unique within account where not null)
    def _conflict(field, value):
        if value is None:
            return None
        for p in profiles:
            if p.get("account_id") != account_id:
                continue
            if p.get("id") == profile_id:
                continue
            if p.get(field) == value:
                return p
        return None

    for field, value in [("email", email), ("phone", phone), ("external_id", external_id)]:
        if value is not None and value != prof.get(field):
            c = _conflict(field, value)
            if c is not None:
                request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "CONFLICT", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
                _save("request_logs.json", request_logs)
                return _err("CONFLICT", f"{field} would collide with another profile in this account", existing_profile_id=c.get("id"))

    # Apply changes
    changed = False
    for field, value in [("email", email), ("phone", phone), ("external_id", external_id),
                         ("first_name", first_name), ("last_name", last_name),
                         ("location", location), ("properties", properties), ("consent", consent)]:
        if value is not None and value != prof.get(field):
            prof[field] = value
            changed = True

    if status is not None and status != prof.get("status"):
        prof["status"] = status
        changed = True
        # deleted_at invariant
        if status == "deleted":
            prof["deleted_at"] = now
        else:
            prof["deleted_at"] = None

    # Enforce identifier presence for active/suppressed
    resulting_status = prof.get("status")
    if resulting_status in ["active", "suppressed"]:
        if prof.get("email") is None and prof.get("phone") is None and prof.get("external_id") is None:
            request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "VALIDATION_ERROR", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "Active/suppressed profiles must have at least one identifier")

    # No success without effect
    if not changed:
        request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "error", "error_code": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "No changes applied (no fields updated)")

    prof["updated_at"] = now
    profiles[idx] = prof
    _save("profiles.json", profiles)

    request_logs.append({"id": "rl_" + secrets.token_hex(8), "endpoint": endpoint, "account_id": account_id, "status": "ok", "error_code": None, "timestamp": now, "latency_ms": int((time.time() - t0) * 1000)})
    _save("request_logs.json", request_logs)
    return {"data": prof}

def delete_profile(profile_id, delete_mode=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, account_id=None, credential_id=None, error_code=None):
        latency_ms = int((datetime.datetime.utcnow() - _t0).total_seconds() * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "ts": _now(),
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _enforce_limits(account_id):
        # Best-effort limits. If no limits file exists, allow.
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            limits = []
        row = None
        for r in limits:
            if isinstance(r, dict) and r.get("account_id") == account_id:
                row = r
                break
        if not row:
            return None

        now = datetime.datetime.utcnow()
        window_s = row.get("window_seconds", 60)
        max_req = row.get("max_requests", None)
        daily_quota = row.get("daily_quota", None)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        if isinstance(max_req, int) and max_req >= 0 and isinstance(window_s, int) and window_s > 0:
            cutoff = now - datetime.timedelta(seconds=window_s)
            c = 0
            for l in logs:
                if not isinstance(l, dict):
                    continue
                if l.get("account_id") != account_id:
                    continue
                ts = l.get("ts")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        c += 1
            if c >= max_req:
                return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window_s, max_requests=max_req)

        if isinstance(daily_quota, int) and daily_quota >= 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            c = 0
            for l in logs:
                if not isinstance(l, dict):
                    continue
                if l.get("account_id") != account_id:
                    continue
                ts = l.get("ts")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= day_start:
                        c += 1
            if c >= daily_quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota=daily_quota)

        return None

    endpoint = "delete_profile"

    # Validate inputs
    if not isinstance(profile_id, str) or not profile_id.strip():
        _log(endpoint, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "profile_id must be a non-empty string.")
    if delete_mode is None:
        delete_mode = "request"
    if delete_mode not in ("hard", "request"):
        _log(endpoint, 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "delete_mode must be one of: hard, request.")

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        _log(endpoint, 500, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "profiles store is unavailable.")

    idx = None
    prof = None
    for i, p in enumerate(profiles):
        if isinstance(p, dict) and p.get("id") == profile_id:
            idx = i
            prof = p
            break
    if not prof:
        _log(endpoint, 404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Profile not found.")

    account_id = prof.get("account_id")
    # Ambient auth: choose a working account. Here, any account can act if it exists and is active.
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(endpoint, 500, account_id=account_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available.")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active":
            acct = a
            break
    if not acct:
        # If the profile references an account that isn't usable, treat as unauthorized for this call.
        _log(endpoint, 401, account_id=account_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller is not authorized to access this profile's account.")

    lim_err = _enforce_limits(account_id)
    if lim_err:
        _log(endpoint, 429 if lim_err["error"]["code"] == "RATE_LIMIT" else 403, account_id=account_id, error_code=lim_err["error"]["code"])
        return lim_err

    # Apply business rules / transitions
    now = _now()

    if delete_mode == "hard":
        # In this service schema, profiles are soft-deleted; "hard" is treated as immediate delete transition.
        # Conflict if already deleted (no effect).
        if prof.get("status") == "deleted":
            _log(endpoint, 409, account_id=account_id, error_code="CONFLICT")
            return _err("CONFLICT", "Profile is already deleted.")
        # Transition to deleted is allowed from active/suppressed/deletion_requested.
        if prof.get("status") not in ("active", "suppressed", "deletion_requested"):
            _log(endpoint, 409, account_id=account_id, error_code="CONFLICT")
            return _err("CONFLICT", "Requested deletion is not allowed for the profile's current status.", status=prof.get("status"))

        prof["status"] = "deleted"
        prof["deleted_at"] = now
        prof["updated_at"] = now
        profiles[idx] = prof
        _save("profiles.json", profiles)

        # Invalidate future event ingestion for that profile:
        # Mark any events with event_time > now as invalid (best effort without parsing event_time errors).
        em = _load("events_metrics.json")
        changed = False
        if isinstance(em, list):
            for r in em:
                if not isinstance(r, dict):
                    continue
                if r.get("record_type") != "event":
                    continue
                if r.get("account_id") != account_id:
                    continue
                if r.get("profile_id") != profile_id:
                    continue
                et = r.get("event_time")
                if not isinstance(et, str):
                    continue
                try:
                    et_dt = datetime.datetime.fromisoformat(et.replace("Z", "+00:00")).replace(tzinfo=None)
                    now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if et_dt > now_dt and r.get("status") != "invalid":
                    # only ingested -> invalid is legal, but enforce by setting to invalid only if ingested
                    if r.get("status") == "ingested":
                        r["status"] = "invalid"
                        r["updated_at"] = now
                        changed = True
        if changed:
            _save("events_metrics.json", em)

        _log(endpoint, 200, account_id=account_id)
        return {"data": prof}

    # delete_mode == "request"
    if prof.get("status") == "deleted":
        _log(endpoint, 409, account_id=account_id, error_code="CONFLICT")
        return _err("CONFLICT", "Cannot request deletion for a deleted profile.")

    # Transition to deletion_requested only allowed from active/suppressed
    if prof.get("status") not in ("active", "suppressed"):
        _log(endpoint, 409, account_id=account_id, error_code="CONFLICT")
        return _err("CONFLICT", "Requested deletion is not allowed for the profile's current status.", status=prof.get("status"))

    prof["status"] = "deletion_requested"
    prof["updated_at"] = now
    # deleted_at must remain null unless status=deleted
    prof["deleted_at"] = None
    profiles[idx] = prof
    _save("profiles.json", profiles)

    _log(endpoint, 200, account_id=account_id)
    return {"data": prof}

def get_lists(account_id, name=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
