    if status is not None and status not in ("active", "archived"):
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(endpoint, 500, "NOT_FOUND")
        return _err("NOT_FOUND", "accounts store is unavailable.")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct:
        _log(endpoint, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found.")
    if acct.get("status") != "active":
        _log(endpoint, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller is not authorized to access this account.")

    lim_err = _enforce_limits()
    if lim_err:
        _log(endpoint, 429 if lim_err["error"]["code"] == "RATE_LIMIT" else 403, lim_err["error"]["code"])
        return lim_err

    audiences = _load("audiences.json")
    if not isinstance(audiences, list):
        audiences = []

    rows = []
    for r in audiences:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        if r.get("type") != "list":
            continue
        if name is not None and r.get("name") != name:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _k(x):
        v = x.get(key)
        return "" if v is None else v

    rows.sort(key=_k, reverse=desc)

    # Cursor decode/encode: base64 of integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw.split(":", 1)[1])
            else:
                offset = int(raw)
            if offset < 0:
                offset = 0
        except Exception:
            _log(endpoint, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid or expired.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8")

    _log(endpoint, 200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort
        }
    }

