def add_profiles_to_list(account_id, list_id, profile_ids, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_profiles_to_list"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(account_id_val):
        limits = _load("limits.json")
        if not isinstance(limits, list):
            return None
        req_per_min = 120
        req_per_day = 20000
        for r in limits:
            if r.get("account_id") == account_id_val and r.get("endpoint") in (endpoint, "*"):
                rpm = r.get("requests_per_minute")
                rpd = r.get("requests_per_day")
                if isinstance(rpm, int) and rpm > 0:
                    req_per_min = rpm
                if isinstance(rpd, int) and rpd > 0:
                    req_per_day = rpd

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        today = now.date()
        rpm_count = 0
        rpd_count = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id_val:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                rpm_count += 1
            if ts.date() == today:
                rpd_count += 1
        if rpm_count >= req_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if rpd_count >= req_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validation
    acct_pat = re.compile(r"^klv_acct_[0-9A-HJKMNP-TV-Z]{10,}$")
    aud_pat = re.compile(r"^klv_aud_[0-9A-HJKMNP-TV-Z]{10,}$")
    prof_pat = re.compile(r"^klv_prof_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(account_id, str) or not acct_pat.match(account_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not isinstance(list_id, str) or not aud_pat.match(list_id):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "list_id is malformed", field="list_id")
    if not isinstance(profile_ids, list) or len(profile_ids) < 1:
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "profile_ids must be a non-empty array", field="profile_ids")
    for i, pid in enumerate(profile_ids):
        if not isinstance(pid, str) or not prof_pat.match(pid):
            _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR", meta={"bad_index": i})
            return _err("VALIDATION_ERROR", "profile_ids contains a malformed id", field="profile_ids", index=i)

    lim_err = _enforce_limits(account_id)
    if lim_err:
        _log("error", account_id_val=account_id, error_code=lim_err["error"]["code"])
        return lim_err

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)

    audiences = _load("audiences.json")
    if not isinstance(audiences, list):
        audiences = []
    aud = next((a for a in audiences if a.get("id") == list_id and a.get("account_id") == account_id), None)
    if not aud:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "List not found", list_id=list_id)
    if aud.get("type") != "list":
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "list_id does not refer to a list-type audience", field="list_id")

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []
    prof_by_id = {p.get("id"): p for p in profiles if p.get("account_id") == account_id}
    missing = [pid for pid in profile_ids if pid not in prof_by_id]
    if missing:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND", meta={"missing_profile_ids": missing[:20]})
        return _err("NOT_FOUND", "One or more profiles not found in account", missing_profile_ids=missing)

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    # Unique(account_id, audience_id, profile_id) where resource_type='list_membership'
    existing = set()
    for r in resources:
        if r.get("resource_type") == "list_membership" and r.get("account_id") == account_id:
            existing.add((r.get("audience_id"), r.get("profile_id")))

    created = []
    already = []
    now = _now()

    # Deterministic-ish id generation (monotonic within file)
    def _next_id(rows):
        return f"klv_res_{int(time.time()*1000)}_{os.getpid()}_{len(rows)+1}"

    for pid in profile_ids:
        key = (list_id, pid)
        if key in existing:
            already.append({"audience_id": list_id, "profile_id": pid, "resource_type": "list_membership"})
            continue
        row = {
            "id": _next_id(resources),
            "account_id": account_id,
            "resource_type": "list_membership",
            "external_key": None,
            "name": None,
            "status": "active",
            "parent_id": None,
            "profile_id": pid,
            "audience_id": list_id,
            "tag_id": None,
            "target_resource_id": None,
            "target_resource_type": None,
            "body": None,
            "analytics": None,
            "created_at": now,
            "updated_at": now,
        }
        resources.append(row)
        existing.add(key)
        created.append(row)

    if not created and not already:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No memberships processed")

    if created:
        _save("resources.json", resources)

    resp = {
        "data": {
            "list_id": list_id,
            "account_id": account_id,
            "created_memberships": created,
            "existing_memberships": already,
            "created_count": len(created),
            "existing_count": len(already),
            "requested_count": len(profile_ids),
        }
    }
    _log("ok", account_id_val=account_id, meta={"created": len(created), "existing": len(already)})
    return resp

def get_segments(account_id, status=None, search=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")

    def _load(n):
