            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _mk_cursor(payload_dict):
        raw = json.dumps(payload_dict, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _read_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log_call(endpoint, account_id_val, status_val, credential_id=None, latency_ms=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "klv_req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id_val,
            "credential_id": credential_id,
            "status": status_val,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, account_id_val):
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute")
        quota = limits.get("quota_per_day")
        if rate is None and quota is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        if rate is not None:
            try:
                rate = int(rate)
            except Exception:
                rate = None
            if rate is not None:
                window_start = now - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    if r.get("account_id") != account_id_val:
                        continue
                    ts = _parse_dt(r.get("timestamp"))
                    if ts is None:
                        continue
                    if ts >= window_start:
                        cnt += 1
                if cnt >= rate:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        if quota is not None:
            try:
                quota = int(quota)
            except Exception:
                quota = None
            if quota is not None:
                day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                cnt = 0
                for r in logs:
                    if r.get("account_id") != account_id_val:
                        continue
                    ts = _parse_dt(r.get("timestamp"))
                    if ts is None:
                        continue
                    if ts >= day_start:
                        cnt += 1
                if cnt >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    start = time.time()
    endpoint = "get_segments"

    if not isinstance(account_id, str) or re.match(r"^klv_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id) is None:
        out = _err("VALIDATION_ERROR", "account_id is malformed")
        _log_call(endpoint, account_id if isinstance(account_id, str) else None, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
        return out

    if status is not None and status not in ("active", "archived"):
        out = _err("VALIDATION_ERROR", "status is invalid", allowed=["active", "archived"])
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
        return out

    if search is not None and not isinstance(search, str):
        out = _err("VALIDATION_ERROR", "search must be a string")
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
        return out

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            out = _err("VALIDATION_ERROR", "limit must be an integer")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out
        if limit < 1 or limit > 200:
            out = _err("VALIDATION_ERROR", "limit out of range (1-200)")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out
        limit_val = limit

    if sort is None:
        sort_val = "-created_at"
    else:
        if sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
            out = _err("VALIDATION_ERROR", "sort is invalid")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out
        sort_val = sort

    cur = None
    if cursor is not None:
        cur = _read_cursor(cursor)
        if cur is None or cur.get("v") != 1 or cur.get("account_id") != account_id or cur.get("endpoint") != endpoint:
            out = _err("VALIDATION_ERROR", "cursor is invalid")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out
        if cur.get("sort") != sort_val or cur.get("status") != status or cur.get("search") != (search or None):
            out = _err("VALIDATION_ERROR", "cursor does not match query parameters")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out

    limerr = _enforce_limits(endpoint, account_id)
    if limerr:
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": limerr["error"]})
        return limerr

    accounts = _load("accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        out = _err("NOT_FOUND", "Account not found")
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
        return out

    audiences = _load("audiences.json")
    rows = [a for a in audiences if a.get("account_id") == account_id and a.get("type") == "segment"]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    if search:
        s = search.casefold()
        def _txt(x):
            return (x or "").casefold()
        rows = [r for r in rows if (s in _txt(r.get("name")) or s in _txt(r.get("description")))]

    # Sorting
    reverse = False
    key = sort_val
    if sort_val.startswith("-"):
        reverse = True
        key = sort_val[1:]

    def _k(r):
        if key in ("created_at", "updated_at"):
            dt = _parse_dt(r.get(key))
            return dt or datetime.datetime.min.replace(tzinfo=None)
        v = r.get(key)
        return (v or "").casefold()

    rows.sort(key=_k, reverse=reverse)

    # Pagination via offset cursor
    offset = 0
    if cur:
        try:
            offset = int(cur.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset:offset + limit_val]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = _mk_cursor({
            "v": 1,
            "endpoint": endpoint,
            "account_id": account_id,
            "offset": next_offset,
            "limit": limit_val,
            "sort": sort_val,
            "status": status,
            "search": search or None
        })

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_val,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_val,
            "status": status,
            "search": search
        }
    }
    _log_call(endpoint, account_id, "ok", latency_ms=int((time.time() - start) * 1000), meta={"returned": len(page), "total": total})
    return resp

