            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out
        # Must match query params
        if cur.get("sort") != sort_val or cur.get("status") != status or cur.get("source") != source or cur.get("profile_id") != profile_id or cur.get("metric_id") != metric_id or cur.get("since") != since or cur.get("until") != until:
            out = _err("VALIDATION_ERROR", "cursor does not match query parameters")
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out

    limerr = _enforce_limits(endpoint, account_id)
    if limerr:
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": limerr["error"]})
        return limerr

    accounts = _load("accounts.json")
    if not any(a.get("id") == account_id for a in accounts):
        out = _err("NOT_FOUND", "Account not found")
        _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
        return out

    # Validate referenced filters belong to account (if present)
    if profile_id is not None:
        profiles = _load("profiles.json")
        p = next((x for x in profiles if x.get("id") == profile_id and x.get("account_id") == account_id), None)
        if p is None:
            out = _err("NOT_FOUND", "profile_id not found for account", profile_id=profile_id)
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out

    if metric_id is not None:
        em = _load("events_metrics.json")
        m = next((x for x in em if x.get("id") == metric_id and x.get("account_id") == account_id and x.get("record_type") == "metric"), None)
        if m is None:
            out = _err("NOT_FOUND", "metric_id not found for account", metric_id=metric_id)
            _log_call(endpoint, account_id, "error", latency_ms=int((time.time() - start) * 1000), meta={"error": out["error"]})
            return out

    rows = _load("events_metrics.json")
    if not isinstance(rows, list):
        rows = []
    rows = [r for r in rows if r.get("account_id") == account_id and r.get("record_type") == "event"]

    if profile_id is not None:
        rows = [r for r in rows if r.get("profile_id") == profile_id]
    if metric_id is not None:
        rows = [r for r in rows if r.get("metric_id") == metric_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if source is not None:
        rows = [r for r in rows if r.get("source") == source]

    if since_dt is not None:
        def _ge_since(r):
            dt = _parse_dt(r.get("event_time"))
            return dt is not None and dt >= since_dt
        rows = [r for r in rows if _ge_since(r)]
    if until_dt is not None:
        def _lt_until(r):
            dt = _parse_dt(r.get("event_time"))
            return dt is not None and dt < until_dt
        rows = [r for r in rows if _lt_until(r)]

    reverse = False
    key = sort_val
    if sort_val.startswith("-"):
        reverse = True
        key = sort_val[1:]

    def _k(r):
        dt = _parse_dt(r.get(key))
        return dt or datetime.datetime.min.replace(tzinfo=None)

    rows.sort(key=_k, reverse=reverse)

    # Pagination (offset)
    offset = 0
    if cur:
        try:
            offset = int(cur.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset:offset + limit_val]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = _mk_cursor({
            "v": 1,
            "endpoint": endpoint,
            "account_id": account_id,
            "offset": next_offset,
            "limit": limit_val,
            "sort": sort_val,
            "profile_id": profile_id,
            "metric_id": metric_id,
            "since": since,
            "until": until,
            "status": status,
            "source": source
        })

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_val,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_val,
            "filters": {
                "profile_id": profile_id,
                "metric_id": metric_id,
                "since": since,
                "until": until,
                "status": status,
                "source": source
            }
        }
    }
    _log_call(endpoint, account_id, "ok", latency_ms=int((time.time() - start) * 1000), meta={"returned": len(page), "total": total})
    return resp

def create_event(account_id, profile_id, metric_id, event_time, event_properties=None, event_value=None, source=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_event"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(account_id_val):
        limits = _load("limits.json")
        if not isinstance(limits, list):
            return None
        req_per_min = 120
        req_per_day = 20000
        for r in limits:
            if r.get("account_id") == account_id_val and r.get("endpoint") in (endpoint, "*"):
                rpm = r.get("requests_per_minute")
                rpd = r.get("requests_per_day")
                if isinstance(rpm, int) and rpm > 0:
                    req_per_min = rpm
                if isinstance(rpd, int) and rpd > 0:
                    req_per_day = rpd

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        today = now.date()
        rpm_count = 0
        rpd_count = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            if r.get("account_id") != account_id_val:
                continue
            ts = _parse_rfc3339(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                rpm_count += 1
            if ts.date() == today:
                rpd_count += 1
        if rpm_count >= req_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if rpd_count >= req_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    acct_pat = re.compile(r"^klv_acct_[0-9A-HJKMNP-TV-Z]{10,}$")
    prof_pat = re.compile(r"^klv_prof_[0-9A-HJKMNP-TV-Z]{10,}$")
    met_pat = re.compile(r"^klv_met_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(account_id, str) or not acct_pat.match(account_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not isinstance(profile_id, str) or not prof_pat.match(profile_id):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "profile_id is malformed", field="profile_id")
    if not isinstance(metric_id, str) or not met_pat.match(metric_id):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metric_id is malformed", field="metric_id")

    et = _parse_rfc3339(event_time)
    if not et:
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "event_time must be a valid RFC3339 date-time", field="event_time")

    if event_properties is not None and not isinstance(event_properties, dict):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "event_properties must be an object", field="event_properties")

    if event_value is not None:
        if not isinstance(event_value, (int, float)) or (isinstance(event_value, bool)):
            _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "event_value must be a number", field="event_value")
        if event_value < 0:
            _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "event_value must be >= 0", field="event_value")

    if source is not None and not isinstance(source, str):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source must be a string", field="source")

    lim_err = _enforce_limits(account_id)
    if lim_err:
        _log("error", account_id_val=account_id, error_code=lim_err["error"]["code"])
        return lim_err

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)

    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []
    prof = next((p for p in profiles if p.get("id") == profile_id and p.get("account_id") == account_id), None)
    if not prof:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Profile not found", profile_id=profile_id)
    if prof.get("status") == "deleted":
        _log("error", account_id_val=account_id, error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create events for a deleted profile", profile_id=profile_id)

    em = _load("events_metrics.json")
    if not isinstance(em, list):
        em = []
    metric = next((r for r in em if r.get("id") == metric_id and r.get("account_id") == account_id and r.get("record_type") == "metric"), None)
    if not metric:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Metric not found", metric_id=metric_id)

    now = _now()
    # If profile has deletion_requested, we still allow event creation but mark invalid? Business rules only forbid deleted.
    status_val = "ingested"

    # If there is a deletion_request resource in pending/fulfilled? Only deleted prevents ingestion; keep ingested.
    if prof.get("status") == "deleted":
        status_val = "invalid"

    new_id = f"klv_evt_{int(time.time()*1000)}_{os.getpid()}_{len(em)+1}"
    row = {
        "id": new_id,
        "account_id": account_id,
        "record_type": "event",
        "metric_id": metric_id,
        "metric_name": None,
        "metric_unit": None,
        "profile_id": profile_id,
        "event_time": et.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "event_properties": event_properties if event_properties is not None else {},
        "event_value": float(event_value) if isinstance(event_value, (int, float)) and not isinstance(event_value, bool) else (None if event_value is None else event_value),
        "source": source,
        "status": status_val,
        "created_at": now,
        "updated_at": now,
    }
    em.append(row)
    _save("events_metrics.json", em)

    _log("ok", account_id_val=account_id, meta={"event_id": new_id, "status": status_val})
    return {"data": row}

def get_metrics(account_id, status=None, search=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    used_credential = None
    endpoint = "get_metrics"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_audit(ok, code=None):
        latency_ms = int((time.time() - t0) * 1000)
        audits = _load("audit_log.json")
        audits.append({
            "id": f"klv_aud_{int(time.time()*1000)}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential_id": used_credential,
            "status": "success" if ok else "error",
            "error_code": None if ok else code,
            "latency_ms": latency_ms
        })
        _save("audit_log.json", audits)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-HJKMNP-TV-Z]{10,}$", account_id):
        e = _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")
        _append_audit(False, e["error"]["code"])
        return e
    allowed_status = {"active", "archived", "ingested", "invalid"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(allowed_status))
        _append_audit(False, e["error"]["code"])
        return e
    if search is not None and not isinstance(search, str):
        e = _err("VALIDATION_ERROR", "search must be a string.", field="search")
        _append_audit(False, e["error"]["code"])
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _append_audit(False, e["error"]["code"])
        return e
    sort_allowed = {"created_at", "-created_at", "updated_at", "-updated_at", "metric_name", "-metric_name"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in sort_allowed:
        e = _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=sorted(sort_allowed))
        _append_audit(False, e["error"]["code"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _append_audit(False, e["error"]["code"])
        return e

    # AUTH ambient: account must exist and not closed
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        e = _err("NOT_FOUND", "Account not found.", field="account_id")
        _append_audit(False, e["error"]["code"])
        return e
    if acct.get("status") == "closed":
        e = _err("UNAUTHORIZED", "Not authorized to read metrics for this account.")
        _append_audit(False, e["error"]["code"])
        return e

    rows = _load("events_metrics.json")
    metrics = [r for r in rows if isinstance(r, dict) and r.get("account_id") == account_id and r.get("record_type") == "metric"]

    if status is not None:
        metrics = [m for m in metrics if m.get("status") == status]

    if search:
        q = search.casefold()
        metrics = [m for m in metrics if (m.get("metric_name") or "").casefold().find(q) != -1]

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _k(m):
        v = m.get(key)
        if v is None:
            return ""
        return v

    metrics.sort(key=_k, reverse=desc)

    # Pagination cursor as base64 json {"o": offset}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("o"), int) and obj["o"] >= 0:
                offset = obj["o"]
            else:
                e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
                _append_audit(False, e["error"]["code"])
                return e
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _append_audit(False, e["error"]["code"])
            return e

    total = len(metrics)
    page = metrics[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"o": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _append_audit(True)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

