        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Relax validation to actual datastore ids (some fixtures may not be ULID-like)
    if not isinstance(campaign_id, str) or not campaign_id.strip():
