    t0 = time.time()
    endpoint = "get_campaign_messages"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")
    cid = campaign_id.strip()
    if not re.match(r"^(klv_res_|cmp_)[A-Za-z0-9_]{6,}$", cid):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    # Resolve campaign row: by id or by external_key
    camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("id") == cid), None)
    if not camp:
        camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("external_key") == cid), None)
    if not camp:
        _log("ok", meta={"found_campaign": False})
        return _err("NOT_FOUND", "Campaign not found", campaign_id=cid)

    account_id = camp.get("account_id")
    msgs = [r for r in resources if r.get("resource_type") == "campaign_message" and r.get("account_id") == account_id and r.get("parent_id") == camp.get("id")]

    key = sort.lstrip("-")
    reverse = sort.startswith("-")

    def _keyfunc(r):
        v = r.get(key)
        # ISO timestamps sort lexicographically when normalized; fallback to empty
        return v if isinstance(v, str) else ""

    msgs.sort(key=_keyfunc, reverse=reverse)

    start = 0
    if cursor:
        # Cursor is opaque; accept raw ids or base64-encoded ids
        cur = None
        if isinstance(cursor, str):
            cur = cursor
            try:
                cur_dec = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                cur2 = cur_dec.decode("utf-8", "ignore")
                if cur2:
                    cur = cur2
            except Exception:
                pass
        if cur:
            for i, r in enumerate(msgs):
                if r.get("id") == cur:
                    start = i + 1
                    break

    page = msgs[start:start + limit]
    has_more = start + limit < len(msgs)
    next_cursor = None
    if has_more and page:
        next_cursor = base64.urlsafe_b64encode(page[-1].get("id", "").encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok", account_id_val=account_id, meta={"returned": len(page), "total": len(msgs), "has_more": has_more})
    return {
        "data": page,
        "meta": {
            "total": len(msgs),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "campaign_id": camp.get("id"),
        },
    }

def get_campaign_recipient_estimation(campaign_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_campaign_recipient_estimation"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")
    cid = campaign_id.strip()
    if not re.match(r"^(klv_res_|cmp_)[A-Za-z0-9_]{6,}$", cid):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("id") == cid), None)
    if not camp:
        camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("external_key") == cid), None)
    if not camp:
        _log("ok", meta={"found": False})
        return _err("NOT_FOUND", "Campaign not found", campaign_id=cid)

    account_id = camp.get("account_id")
    analytics = camp.get("analytics") if isinstance(camp.get("analytics"), dict) else None
    if analytics and isinstance(analytics.get("recipient_estimate"), (int, float)) and not isinstance(analytics.get("recipient_estimate"), bool):
        est = int(analytics.get("recipient_estimate"))
        _log("ok", account_id_val=account_id, meta={"source": "cache", "estimate": est})
        return {"data": {"campaign_id": camp.get("id"), "recipient_estimate": est, "source": "cache"}}

    # Compute fallback: if campaign body includes list_id(s), count list memberships excluding deleted profiles
    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []
    active_profile_ids = set(p.get("id") for p in profiles if p.get("account_id") == account_id and p.get("status") != "deleted")

    body = camp.get("body") if isinstance(camp.get("body"), dict) else {}
    target_list_ids = []
    if isinstance(body, dict):
        for k in ("list_id", "audience_id", "list_ids", "audience_ids"):
            v = body.get(k)
            if isinstance(v, str):
                target_list_ids.append(v)
            elif isinstance(v, list):
                target_list_ids.extend([x for x in v if isinstance(x, str)])
    target_list_ids = list(dict.fromkeys(target_list_ids))

    est = 0
    source_val = "computed"
    if target_list_ids:
        members = [r for r in resources if r.get("resource_type") == "list_membership" and r.get("account_id") == account_id and r.get("audience_id") in target_list_ids]
        est = len(set(r.get("profile_id") for r in members if r.get("profile_id") in active_profile_ids))
    else:
        # No targeting info; conservative estimate: 0
        est = 0
        source_val = "computed_no_targeting"

    # Persist cache
    if analytics is None:
        analytics = {}
    analytics["recipient_estimate"] = est
    analytics["recipient_estimate_updated_at"] = _now()
    for i, r in enumerate(resources):
        if r.get("id") == camp.get("id"):
            resources[i] = dict(r)
            resources[i]["analytics"] = analytics
            resources[i]["updated_at"] = _now()
            break
    _save("resources.json", resources)

    _log("ok", account_id_val=account_id, meta={"source": source_val, "estimate": est})
    return {"data": {"campaign_id": camp.get("id"), "recipient_estimate": est, "source": source_val}}

def get_campaign_metrics(campaign_id, start_time=None, end_time=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_campaign_metrics"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is not in the expected format", field="campaign_id")
    cid = campaign_id.strip()
    if not re.match(r"^(klv_res_|cmp_)[A-Za-z0-9_]{6,}$", cid):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is not in the expected format", field="campaign_id")

    st = _parse_rfc3339(start_time) if start_time is not None else None
    et = _parse_rfc3339(end_time) if end_time is not None else None
    if start_time is not None and st is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be a valid RFC3339 date-time", field="start_time")
    if end_time is not None and et is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be a valid RFC3339 date-time", field="end_time")
    if st and et and not (et > st):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be after start_time", field="end_time")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("id") == cid), None)
    if not camp:
        camp = next((r for r in resources if r.get("resource_type") == "campaign" and r.get("external_key") == cid), None)
    if not camp:
        _log("ok", meta={"found": False})
        return _err("NOT_FOUND", "Campaign not found", campaign_id=cid)

    account_id = camp.get("account_id")
    analytics = camp.get("analytics") if isinstance(camp.get("analytics"), dict) else None
    if analytics and isinstance(analytics.get("metrics"), dict):
        _log("ok", account_id_val=account_id, meta={"source": "cache"})
        return {"data": {"campaign_id": camp.get("id"), "metrics": analytics.get("metrics"), "source": "cache"}}

    # Compute minimal metrics from events by looking for event_properties.campaign_id == camp.id
    evm = _load("events_metrics.json")
    if not isinstance(evm, list):
        evm = []
    events = [e for e in evm if e.get("account_id") == account_id and e.get("record_type") == "event" and e.get("status") == "ingested"]

    def _in_window(e):
        dt = _parse_rfc3339(e.get("event_time"))
        if not dt:
            return False
        if st and dt < st:
            return False
        if et and dt >= et:
            return False
        return True

    camp_events = []
    for e in events:
        props = e.get("event_properties")
        if isinstance(props, dict) and (props.get("campaign_id") == camp.get("id") or props.get("campaign_id") == cid):
            if _in_window(e):
                camp_events.append(e)

    # Count by metric_name if metric exists
    metric_by_id = {r.get("id"): r for r in evm if r.get("record_type") == "metric" and r.get("account_id") == account_id}
    counts = {}
    revenue = 0.0
    for e in camp_events:
        m = metric_by_id.get(e.get("metric_id"))
        name = (m.get("metric_name") if m else None) or e.get("metric_id") or "unknown"
        counts[name] = counts.get(name, 0) + 1
        if isinstance(e.get("event_value"), (int, float)) and not isinstance(e.get("event_value"), bool):
            revenue += float(e.get("event_value"))

    metrics_payload = {
        "event_counts": counts,
        "total_events": len(camp_events),
        "revenue": revenue,
        "start_time": start_time,
        "end_time": end_time,
    }

    # Persist to campaign analytics
    if analytics is None:
        analytics = {}
    analytics["metrics"] = metrics_payload
    analytics["metrics_updated_at"] = _now()
    for i, r in enumerate(resources):
        if r.get("id") == camp.get("id"):
            resources[i] = dict(r)
            resources[i]["analytics"] = analytics
            resources[i]["updated_at"] = _now()
            break
    _save("resources.json", resources)

    _log("ok", account_id_val=account_id, meta={"source": "computed", "total_events": len(camp_events)})
    return {"data": {"campaign_id": camp.get("id"), "metrics": metrics_payload, "source": "computed"}}

def query_metric_aggregates(metric_id, start_time, end_time, interval, statistic, group_by=None, filter=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs = _load("request_logs.json")
    accounts = _load("accounts.json")
    profiles = _load("profiles.json")
    events = _load("events_metrics.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"klv_req_{int(time.time()*1000)}",
            "endpoint": "query_metric_aggregates",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(metric_id, str) or not re.match(r"^klv_met_[0-9A-Z]{10,}$", metric_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metric_id is invalid", field="metric_id")
    st = _parse_rfc3339(start_time)
    et = _parse_rfc3339(end_time)
    if st is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be a valid RFC 3339 date-time", field="start_time")
    if et is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be a valid RFC 3339 date-time", field="end_time")
    if not (et > st):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be after start_time", field="end_time")

    if interval not in ("hour", "day", "week", "month"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is invalid", field="interval")
    if statistic not in ("count", "sum", "avg", "min", "max"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "statistic is invalid", field="statistic")

    if group_by is None:
        group_by = []
    if not isinstance(group_by, list) or any((not isinstance(x, str) or x not in ("source", "profile_id")) for x in group_by):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_by must be an array of supported fields", field="group_by")
    if len(set(group_by)) != len(group_by):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_by must not contain duplicates", field="group_by")

    if filter is None:
        filter = {}
    if not isinstance(filter, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filter must be an object", field="filter")
    for k in filter.keys():
        if k not in ("profile_id", "source"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "filter contains unsupported fields", field="filter")

    f_profile_id = filter.get("profile_id")
    if f_profile_id is not None:
        if not isinstance(f_profile_id, str) or not re.match(r"^klv_prof_[0-9A-Z]{10,}$", f_profile_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "filter.profile_id is invalid", field="filter.profile_id")
    f_source = filter.get("source")
    if f_source is not None and not isinstance(f_source, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "filter.source must be a string", field="filter.source")

    # Locate metric definition row (and account scope)
    met = None
    for r in events:
        if r.get("id") == metric_id and r.get("record_type") == "metric":
            met = r
            break
    if not met:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Metric not found", metric_id=metric_id)

    account_id = met.get("account_id")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct or acct.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active account context can serve this request")

    # Enforce cross-account filter refs
    prof_account_ok = True
    if f_profile_id is not None:
        prof = next((p for p in profiles if p.get("id") == f_profile_id), None)
        if not prof or prof.get("account_id") != account_id or prof.get("status") == "deleted":
            prof_account_ok = False
    if f_profile_id is not None and not prof_account_ok:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Profile not found in account or is deleted", profile_id=f_profile_id)

    def _bucket_start(dt):
        # dt is UTC aware
        if interval == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if interval == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if interval == "week":
            # ISO week starts Monday
            d0 = dt.replace(hour=0, minute=0, second=0, microsecond=0)
            return d0 - datetime.timedelta(days=d0.weekday())
        # month
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _bucket_next(dt):
        if interval == "hour":
            return dt + datetime.timedelta(hours=1)
        if interval == "day":
            return dt + datetime.timedelta(days=1)
        if interval == "week":
            return dt + datetime.timedelta(days=7)
        # month
        y = dt.year
        m = dt.month + 1
        if m == 13:
            y += 1
            m = 1
        return dt.replace(year=y, month=m, day=1)

    # Collect events (ingested only)
    buckets = {}  # key: (bucket_start_iso, group_tuple) -> stats accumulator
    group_fields = list(group_by)

    def _group_tuple(ev):
        parts = []
        for f in group_fields:
            if f == "source":
                parts.append(ev.get("source"))
            elif f == "profile_id":
                parts.append(ev.get("profile_id"))
        return tuple(parts)

    def _within(dt):
        return (dt >= st) and (dt < et)

    for ev in events:
        if ev.get("account_id") != account_id:
            continue
        if ev.get("record_type") != "event":
            continue
        if ev.get("status") != "ingested":
            continue
        if ev.get("metric_id") != metric_id:
            continue
        if f_profile_id is not None and ev.get("profile_id") != f_profile_id:
            continue
        if f_source is not None and ev.get("source") != f_source:
            continue

        dt = _parse_rfc3339(ev.get("event_time"))
        if dt is None or not _within(dt):
            continue

        b = _bucket_start(dt)
        g = _group_tuple(ev)
        k = (b.isoformat(), g)
        acc = buckets.get(k)
        if acc is None:
            acc = {"count": 0, "sum": 0.0, "min": None, "max": None}
            buckets[k] = acc
        acc["count"] += 1
        val = ev.get("event_value")
        if isinstance(val, (int, float)) and val >= 0:
            fv = float(val)
            acc["sum"] += fv
            acc["min"] = fv if acc["min"] is None else min(acc["min"], fv)
            acc["max"] = fv if acc["max"] is None else max(acc["max"], fv)
        else:
            # For non-numeric event_value: count still applies; sum/avg/min/max ignore nulls.
            pass

    # Produce deterministic list of all buckets in range, even if empty? Real APIs vary; we return only non-empty buckets.
    results = []
    for (b_iso, g), acc in buckets.items():
        out = {
            "bucket_start": b_iso,
            "bucket_end": _bucket_next(datetime.datetime.fromisoformat(b_iso)).isoformat(),
        }
        for i, f in enumerate(group_fields):
            out[f] = g[i]
        if statistic == "count":
            out["value"] = acc["count"]
        elif statistic == "sum":
            out["value"] = acc["sum"]
        elif statistic == "avg":
            out["value"] = (acc["sum"] / acc["count"]) if acc["count"] > 0 else None
        elif statistic == "min":
            out["value"] = acc["min"]
        elif statistic == "max":
            out["value"] = acc["max"]
        results.append(out)

    # Sort by bucket_start then group fields
    def _sort_key(r):
        keys = [r.get("bucket_start")]
        for f in group_fields:
            v = r.get(f)
            keys.append("" if v is None else str(v))
        return tuple(keys)

    results.sort(key=_sort_key)

    _log("ok")
    return {
        "metric_id": metric_id,
        "account_id": account_id,
        "start_time": start_time,
        "end_time": end_time,
        "interval": interval,
        "statistic": statistic,
        "group_by": group_fields,
        "filter": filter,
        "data": results,
    }

def get_campaign_performance(campaign_id, start_time=None, end_time=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_campaign_performance"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(campaign_id, str) or not campaign_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")
    cid = campaign_id.strip()
    if not re.match(r"^(klv_res_|cmp_)[A-Za-z0-9_]{6,}$", cid):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is malformed", field="campaign_id")

    st = _parse_rfc3339(start_time) if start_time is not None else None
    et = _parse_rfc3339(end_time) if end_time is not None else None
    if start_time is not None and st is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be a valid RFC3339 date-time", field="start_time")
    if end_time is not None and et is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be a valid RFC3339 date-time", field="end_time")
    if st and et and not (et > st):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be after start_time", field="end_time")

    # Reuse metrics (computed/cached) then derive rates
    m = get_campaign_metrics(campaign_id=cid, start_time=start_time, end_time=end_time)
    if isinstance(m, dict) and m.get("error"):
        # get_campaign_metrics already logged its own request; still log this endpoint too
        _log("error", error_code=m["error"]["code"])
        return m

    metrics = (m.get("data") or {}).get("metrics") or {}
    counts = metrics.get("event_counts") if isinstance(metrics.get("event_counts"), dict) else {}
    total = metrics.get("total_events") if isinstance(metrics.get("total_events"), int) else 0
    revenue = metrics.get("revenue") if isinstance(metrics.get("revenue"), (int, float)) else 0.0

    # Common Klaviyo-like metrics (best-effort): derive open/click rates if present
    def _count_by_name(substr):
        s = 0
        for k, v in counts.items():
            if isinstance(k, str) and substr.lower() in k.lower() and isinstance(v, int):
                s += v
        return s

    opened = _count_by_name("Opened Email")
    clicked = _count_by_name("Clicked Email")
    placed = _count_by_name("Placed Order")

    # Use total as denominator when no send count is available
    denom = total if total > 0 else 0
    open_rate = (opened / denom) if denom else None
    click_rate = (clicked / denom) if denom else None
    conversion_rate = (placed / denom) if denom else None

    perf = {
        "campaign_id": (m.get("data") or {}).get("campaign_id") or cid,
        "start_time": start_time,
        "end_time": end_time,
        "total_events": total,
        "opened": opened,
        "clicked": clicked,
        "placed_order": placed,
        "revenue": float(revenue),
        "open_rate": open_rate,
        "click_rate": click_rate,
        "conversion_rate": conversion_rate,
        "denominator": "total_events",
        "source": (m.get("data") or {}).get("source"),
    }

    # Log with account id if we can find it
    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []
    camp = next((r for r in resources if r.get("resource_type") == "campaign" and (r.get("id") == perf["campaign_id"] or r.get("external_key") == cid)), None)
    _log("ok", account_id_val=(camp.get("account_id") if camp else None))
    return {"data": perf}

def get_flows(account_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs = _load("request_logs.json")
    accounts = _load("accounts.json")
    resources = _load("resources.json")

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"klv_req_{int(time.time()*1000)}",
            "endpoint": "get_flows",
            "timestamp": _now_iso(),
            "status": status_s,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-Z]{10,}$", account_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is invalid", field="account_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "active", "paused", "archived", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if sort is None:
        sort = "-updated_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    # Account must exist and be active to serve request
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account is not active", account_id=account_id)

    # Decode cursor (opaque)
    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if payload.get("account_id") != account_id:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor does not match account_id", field="cursor")
            if payload.get("sort") != sort or payload.get("status") != status:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor does not match query parameters", field="cursor")
            start_index = int(payload.get("offset", 0))
            if start_index < 0:
                raise ValueError("offset")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # Filter flows
    rows = []
    for r in resources:
        if r.get("account_id") != account_id:
            continue
        if r.get("resource_type") != "flow":
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _dt_key(v):
        if not isinstance(v, str):
            return ""
        return v

    reverse = False
    key_field = sort
    if sort.startswith("-"):
        reverse = True
        key_field = sort[1:]

    def _sort_key(r):
        if key_field in ("created_at", "updated_at"):
            return (_dt_key(r.get(key_field)), r.get("id"))
        if key_field == "name":
            nm = r.get("name")
            return ("" if nm is None else str(nm).lower(), r.get("id"))
        return (r.get("id"),)

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start_index:start_index + limit]
    next_cursor = None
    has_more = (start_index + limit) < total
    if has_more:
        payload = {"account_id": account_id, "offset": start_index + limit, "sort": sort, "status": status}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    _log("ok")
    return {
        "account_id": account_id,
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "status": status,
        },
    }

def get_flow(account_id, flow_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
