    def _is_ulid_like(prefix, val):
        return isinstance(val, str) and val.startswith(prefix) and len(val) >= len(prefix) + 6

    allowed_status = {"draft", "active", "paused", "archived"}

    if not _is_ulid_like("klv_acct_", account_id):
        _log("error", "VALIDATION_ERROR", "Malformed account_id")
        return _err("VALIDATION_ERROR", "Malformed account_id")
    if not _is_ulid_like("klv_res_", flow_id):
        _log("error", "VALIDATION_ERROR", "Malformed flow_id")
        return _err("VALIDATION_ERROR", "Malformed flow_id")
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", "VALIDATION_ERROR", "Unsupported status")
        return _err("VALIDATION_ERROR", "Unsupported status", allowed=list(sorted(allowed_status)))

    # Rate limiting (mutations stricter)
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_iso(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        MUT_PER_MIN = 60
        if cnt >= MUT_PER_MIN:
            _log("error", "RATE_LIMIT", "Write rate limit exceeded")
            return _err("RATE_LIMIT", "Write rate limit exceeded")
    except Exception:
        pass

    accounts = _load("accounts.json")
