        _log("error", "UNAUTHORIZED", "Account not active")
        return _err("UNAUTHORIZED", "Account not active")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        _log("error", "NOT_FOUND", "Flow not found")
        return _err("NOT_FOUND", "Flow not found")

    idx = None
    flow = None
    for i, r in enumerate(resources):
        if r.get("id") == flow_id and r.get("account_id") == account_id and r.get("resource_type") == "flow":
            idx = i
            flow = r
            break
    if flow is None:
        _log("error", "NOT_FOUND", "Flow not found")
        return _err("NOT_FOUND", "Flow not found")

    current = flow.get("status")
    # Resource lifecycle transitions (subset relevant to flows)
    transitions = {
        "draft": {"active", "archived"},
        "active": {"paused", "archived"},
        "paused": {"active", "archived"},
        "archived": {"active"},
    }
    if current not in transitions:
        # Flow row corrupted or unsupported state for this endpoint
        _log("error", "CONFLICT", "Flow is in a state that cannot be transitioned by this endpoint")
        return _err("CONFLICT", "Flow is in a state that cannot be transitioned by this endpoint", current_status=current)

    if status == current:
        # Idempotent: no change, but still a "real" effect? Return the same row without writing.
        _log("ok")
        return {"flow": flow}

    if status not in transitions.get(current, set()):
        _log("error", "INVALID_TRANSITION", "Invalid status transition")
        return _err("INVALID_TRANSITION", "Invalid status transition", from_status=current, to_status=status)

    # Apply mutation
    flow2 = dict(flow)
    flow2["status"] = status
    flow2["updated_at"] = _now_iso()
    resources[idx] = flow2
    _save("resources.json", resources)

    _log("ok")
    return {"flow": flow2}

