    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "Invalid limit", minimum=1, maximum=200)

    # Rate limit reads per account per minute for this endpoint
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
