    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED", "Account not active")
        return _err("UNAUTHORIZED", "Account not active")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    templates = [r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "template"]
    if status is not None:
        templates = [r for r in templates if r.get("status") == status]

    # Sorting
    sort_key = sort or "-updated_at"
    reverse = sort_key.startswith("-")
    field = sort_key[1:] if reverse else sort_key

    def _key(r):
        if field in ("created_at", "updated_at"):
            dt = _parse_iso(r.get(field))
            return dt or datetime.datetime.min
        if field == "name":
            v = r.get("name")
            return (v or "").lower()
        return r.get(field)

    try:
        templates.sort(key=_key, reverse=reverse)
    except Exception:
        # If sort fails due to bad types, fail validation-style (service would reject unsupported/malformed)
        _log("error", "VALIDATION_ERROR", "Unable to sort templates with requested sort")
        return _err("VALIDATION_ERROR", "Unable to sort templates with requested sort")

    total = len(templates)

    # Cursor is opaque base64 of integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not decoded.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(decoded.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = templates[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "templates": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort_key,
            "status": status
        }
    }

