def create_template(account_id, name, body, status=None, external_key=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_template"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_val, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status_val,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation (relaxed but correct)
    if not isinstance(account_id, str) or not account_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not isinstance(name, str) or not name.strip():
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required", field="name")
    if not isinstance(body, dict):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object", field="body")
    if not (isinstance(body.get("html"), str) and body.get("html").strip()) and not (isinstance(body.get("text"), str) and body.get("text").strip()):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must include at least one of (html, text)", field="body")

    if status is None:
        status = "draft"
    if status not in ("draft", "active"):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is unsupported", field="status")

    if external_key is not None and not isinstance(external_key, str):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "external_key must be a string", field="external_key")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    # Idempotency by external_key (for templates only)
    if external_key:
        existing = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "template" and r.get("external_key") == external_key), None)
        if existing:
            # If same payload, return existing; otherwise conflict
            same = (existing.get("name") == name and existing.get("status") == status and isinstance(existing.get("body"), dict) and existing.get("body") == body)
            if same:
                _log("ok", account_id_val=account_id, meta={"idempotent": True, "template_id": existing.get("id")})
                return {"data": existing}
            _log("error", account_id_val=account_id, error_code="CONFLICT")
            return _err("CONFLICT", "external_key is already in use for another template in this account", external_key=external_key)

    now = _now()
    new_id = f"klv_res_{int(time.time()*1000)}_{os.getpid()}_{len(resources)+1}"
    row = {
        "id": new_id,
        "account_id": account_id,
        "resource_type": "template",
        "external_key": external_key,
        "name": name,
        "status": status,
        "parent_id": None,
        "profile_id": None,
        "audience_id": None,
        "tag_id": None,
        "target_resource_id": None,
        "target_resource_type": None,
        "body": body,
        "analytics": None,
        "created_at": now,
        "updated_at": now,
    }
    resources.append(row)
    _save("resources.json", resources)
    _log("ok", account_id_val=account_id, meta={"template_id": new_id})
    return {"data": row}

