                continue
            if r.get("account_id") == account_id and r.get("endpoint") == "get_tags":
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
                else:
                    break
        if recent >= 120:
            _log(429, error_code="RATE_LIMIT")
