        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("offset:"):
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            start = int(raw.split("offset:", 1)[1])
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    accounts = _load("accounts.json")
