            "account_id": account_id,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Basic rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reversed(logs):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") == account_id and r.get("endpoint") == "add_tag_to_resource":
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
                else:
                    break
        if recent >= 120:
            _log(429, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-Z]{10,}$", account_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.")
    if not isinstance(tag_id, str) or not re.match(r"^klv_res_[0-9A-Z]{10,}$", tag_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tag_id is malformed.")
    if not isinstance(target_resource_id, str) or not re.match(r"^(klv_res|klv_prof)_[0-9A-Z]{10,}$", target_resource_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "target_resource_id is malformed.")
    allowed_types = {"campaign","campaign_message","flow","template","catalog","catalog_item","profile","form","coupon","webhook","image","product_review"}
    if not isinstance(target_resource_type, str) or target_resource_type not in allowed_types:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "target_resource_type is not supported.")

    accounts = _load("accounts.json")
    acct = None
    for a in accounts if isinstance(accounts, list) else []:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct or acct.get("status") != "active":
        _log(401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller cannot access this account.")

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []
    profiles = _load("profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    # Validate tag exists and is a tag in same account
    tag_row = None
    for r in resources:
        if isinstance(r, dict) and r.get("id") == tag_id and r.get("account_id") == account_id:
            tag_row = r
            break
    if not tag_row or tag_row.get("resource_type") != "tag":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Tag not found.", tag_id=tag_id)

    # Validate target exists in same account and matches type.
    target_obj = None
    if target_resource_type == "profile":
        if not target_resource_id.startswith("klv_prof_"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "target_resource_id must be a profile id when target_resource_type='profile'.")
        for p in profiles:
            if isinstance(p, dict) and p.get("id") == target_resource_id and p.get("account_id") == account_id:
                target_obj = p
                break
        if not target_obj or target_obj.get("status") == "deleted":
            _log(404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Target profile not found.", target_resource_id=target_resource_id)
    else:
        if not target_resource_id.startswith("klv_res_"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "target_resource_id must be a resource id when tagging non-profile targets.")
        for r in resources:
            if isinstance(r, dict) and r.get("id") == target_resource_id and r.get("account_id") == account_id:
                target_obj = r
                break
        if not target_obj or target_obj.get("resource_type") != target_resource_type:
            _log(404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Target resource not found.", target_resource_id=target_resource_id)

    # Unique(account_id, tag_id, target_resource_id) where resource_type='tag_assignment' (idempotent)
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") == account_id and r.get("resource_type") == "tag_assignment":
            if r.get("tag_id") == tag_id and r.get("target_resource_id") == target_resource_id:
                # idempotent success: return existing assignment
                _log(200)
                return {"data": r, "meta": {"idempotent": True}}

    def _new_id(prefix):
        base = int(time.time() * 1000)
        suffix = f"{base:X}{len(resources)+1:X}".upper()
        if len(suffix) < 10:
            suffix = (suffix + "0"*10)[:10]
        return f"{prefix}_{suffix}"

    assignment = {
        "id": _new_id("klv_res"),
        "account_id": account_id,
        "resource_type": "tag_assignment",
        "external_key": None,
        "name": None,
        "status": "active",
        "parent_id": None,
        "profile_id": None,
        "audience_id": None,
        "tag_id": tag_id,
        "target_resource_id": target_resource_id,
        "target_resource_type": target_resource_type,
        "body": None,
        "analytics": None,
        "created_at": now,
        "updated_at": now
    }

    resources.append(assignment)
    _save("resources.json", resources)

    _log(201)
    return {"data": assignment}

def get_webhooks(account_id, limit=None, cursor=None, status=None, q=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}_{len(logs)+1}",
            "timestamp": now,
            "endpoint": "get_webhooks",
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    # Basic rate limit
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in reversed(logs):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") == account_id and r.get("endpoint") == "get_webhooks":
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
                else:
                    break
        if recent >= 120:
            _log(429, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-Z]{10,}$", account_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    allowed_status = {"draft","active","paused","archived","deleted","enabled","disabled","pending","fulfilled","failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is not allowed.")

    allowed_sort = {"created_at","-created_at","updated_at","-updated_at","name","-name"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is not allowed.")

    if q is not None and not isinstance(q, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "q must be a string.")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("offset:"):
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            start = int(raw.split("offset:", 1)[1])
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    accounts = _load("accounts.json")
    acct = None
    for a in accounts if isinstance(accounts, list) else []:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct or acct.get("status") != "active":
        _log(401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller cannot access this account.")

    resources = _load("resources.json")
    rows = []
    for r in resources if isinstance(resources, list) else []:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        if r.get("resource_type") != "webhook":
            continue
        if status is not None and r.get("status") != status:
            continue
        if q:
            nm = r.get("name") or ""
            if not isinstance(nm, str) or q.lower() not in nm.lower():
                continue
        rows.append(r)

    def _key(row):
        v = row.get(sort.lstrip("-"))
        if sort.lstrip("-") in ("created_at", "updated_at"):
            return v if isinstance(v, str) else ""
        return (v or "").lower() if isinstance(v, str) else ""
    reverse = sort.startswith("-")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    has_more = start + limit < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort
        }
    }

def create_webhook(account_id, name, body, external_key=None, status=None, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_webhook"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_val, account_id_val=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"klv_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "account_id": account_id_val,
            "status": status_val,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    acct_pat = re.compile(r"^klv_acct_[0-9A-Z]{10,}$")
    if not isinstance(account_id, str) or not acct_pat.match(account_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not isinstance(name, str) or not name.strip():
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required", field="name")
    if not isinstance(body, dict):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object", field="body")
    if status is None:
        status = "enabled"
    if status not in ("enabled", "disabled"):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of enabled|disabled", field="status")
    if external_key is not None and not isinstance(external_key, str):
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "external_key must be a string", field="external_key")

    # Business rule: body must include valid url and events array
    url = body.get("url") or body.get("destination_url")
    events = body.get("events") or body.get("topics")
    if not isinstance(url, str) or not url.strip():
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook body must include a valid url", field="body.url")
    try:
        u = urllib.parse.urlparse(url)
        if u.scheme not in ("http", "https") or not u.netloc:
            _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook body must include a valid url", field="body.url")
    except Exception:
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook body must include a valid url", field="body.url")
    if not isinstance(events, list) or not all(isinstance(x, str) and x.strip() for x in events) or len(events) == 0:
        _log("error", account_id_val=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook body must include an events array", field="body.events")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", account_id_val=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)

    resources = _load("resources.json")
    if not isinstance(resources, list):
        resources = []

    if external_key:
        conflict = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "webhook" and r.get("external_key") == external_key and r.get("status") != "deleted"), None)
        if conflict:
            _log("error", account_id_val=account_id, error_code="CONFLICT")
            return _err("CONFLICT", "external_key is already in use for another webhook in this account", external_key=external_key)

    now = _now()
    new_id = f"klv_res_{int(time.time()*1000)}_{os.getpid()}_{len(resources)+1}"
    row = {
        "id": new_id,
        "account_id": account_id,
        "resource_type": "webhook",
        "external_key": external_key,
        "name": name,
        "status": status,
        "parent_id": None,
        "profile_id": None,
        "audience_id": None,
        "tag_id": None,
        "target_resource_id": None,
        "target_resource_type": None,
        "body": body,
        "analytics": None,
        "created_at": now,
        "updated_at": now,
    }
    resources.append(row)
    _save("resources.json", resources)
    _log("ok", account_id_val=account_id, meta={"webhook_id": new_id})
    return {"data": row}

