        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_coupons"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "klv_req_" + uuid.uuid4().hex[:20].upper(),
            "timestamp": _now(),
            "endpoint": endpoint,
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("limits.json")
        now = datetime.datetime.utcnow()
        rl = {"requests_per_minute": 240}
        qd = {"requests_per_day": 50000}
        for r in limits:
            if r.get("account_id") == account_id and r.get("endpoint") in (endpoint, "*"):
                rl = r.get("rate_limit_per_minute", rl) if isinstance(r.get("rate_limit_per_minute"), dict) else rl
                qd = r.get("quota_per_day", qd) if isinstance(r.get("quota_per_day"), dict) else qd
        logs = _load("request_logs.json")
        one_min_ago = now - datetime.timedelta(seconds=60)
        today = now.date()
        cnt_min = 0
        cnt_day = 0
        for e in logs:
            if e.get("account_id") != account_id:
                continue
            ts = e.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if e.get("endpoint") == endpoint and dt >= one_min_ago:
                cnt_min += 1
            if dt.date() == today:
                cnt_day += 1
        if isinstance(rl, dict) and isinstance(rl.get("requests_per_minute"), int) and cnt_min >= rl["requests_per_minute"]:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qd, dict) and isinstance(qd.get("requests_per_day"), int) and cnt_day >= qd["requests_per_day"]:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-Z]{10,}$", account_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "account_id is malformed")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    allowed_status = {"draft","active","paused","archived","deleted","enabled","disabled","pending","fulfilled","failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status is not allowed")

    allowed_sort = {"created_at","-created_at","updated_at","-updated_at","name","-name"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort is not allowed")

    if q is not None and not isinstance(q, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "q must be a string")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Auth/account context
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authorized account context found for this request")
    if acct.get("status") != "active":
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Account is not active")

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", meta={"code": lim_err["error"]["code"]})
        return lim_err

    resources = _load("resources.json")
    rows = [r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "coupon"]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    if q is not None and q.strip():
        qs = q.strip().lower()
        def _nm(r):
            n = r.get("name")
            if isinstance(n, str) and n:
                return n
            ek = r.get("external_key")
            return ek if isinstance(ek, str) else ""
        rows = [r for r in rows if qs in (_nm(r).lower())]

    # Sort
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    if key in ("created_at", "updated_at"):
        def kf(r):
            dt = _parse_dt(r.get(key))
            return dt if dt is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        rows.sort(key=kf, reverse=desc)
    elif key == "name":
        def kf(r):
            n = r.get("name")
            if not isinstance(n, str):
                n = ""
            return (n.lower(), r.get("id") or "")
        rows.sort(key=kf, reverse=desc)

    total = len(rows)
    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8") if has_more else None

    _log("ok", meta={"code": "OK", "returned": len(page)})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def create_coupon_code(account_id, body, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, account=None, resource_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "klv_req_" + hashlib.sha1(f"{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:12].upper(),
            "endpoint": "create_coupon_code",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "account_id": account,
            "resource_id": resource_id,
            "error_code": code,
            "error_message": message,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

        usage = _load("usage_counters.json")
        day = now[:10]
        found = None
        for u in usage:
            if u.get("account_id") == account and u.get("date") == day:
                found = u
                break
        if not found:
            found = {"account_id": account, "date": day, "reads": 0, "writes": 0}
            usage.append(found)
        found["writes"] = int(found.get("writes", 0)) + 1
        _save("usage_counters.json", usage)

    def _rate_limit_check(account):
        logs = _load("request_logs.json")
        # 60 req/min/account (soft generic), 2000 req/day/account
        cutoff = time.time() - 60
        per_min = 0
        day = now[:10]
        per_day = 0
        for r in logs:
            if r.get("account_id") != account:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str) and len(ts) >= 20:
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.timestamp() >= cutoff:
                        per_min += 1
                    if ts[:10] == day:
                        per_day += 1
                except Exception:
                    if ts[:10] == day:
                        per_day += 1
        if per_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 2000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^klv_acct_[0-9A-Z]{4,}$", account_id):
        _log("error", "VALIDATION_ERROR", "Invalid account_id format", account=account_id)
        return _err("VALIDATION_ERROR", "Invalid account_id format")
    if not isinstance(body, dict):
        _log("error", "VALIDATION_ERROR", "body must be an object", account=account_id)
        return _err("VALIDATION_ERROR", "body must be an object")

    rl = _rate_limit_check(account_id)
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"], account=account_id)
        return rl

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", "NOT_FOUND", "Account not found", account=account_id)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED", "Account not active", account=account_id)
        return _err("UNAUTHORIZED", "Account not active")

    code = body.get("code")
    if not isinstance(code, str) or not code.strip():
        _log("error", "VALIDATION_ERROR", "code is required", account=account_id)
        return _err("VALIDATION_ERROR", "code is required")

    # Map tool body -> resources coupon body; enforce immutable/unique external_key (coupon code)
    code_norm = code.strip()

    status = body.get("status", None)
    allowed_status = ["draft", "active", "paused", "archived", "deleted", "enabled", "disabled", "pending", "fulfilled", "failed"]
    if status is not None and status not in allowed_status:
        _log("error", "VALIDATION_ERROR", "Unsupported status", account=account_id)
        return _err("VALIDATION_ERROR", "Unsupported status", field="status")
    if status is None:
        status = "draft"

    discount_type = body.get("discount_type", None)
    if discount_type is not None and discount_type not in ("percent", "fixed"):
        _log("error", "VALIDATION_ERROR", "Unsupported discount_type", account=account_id)
        return _err("VALIDATION_ERROR", "Unsupported discount_type", field="discount_type")

    discount_value = body.get("discount_value", None)
    if discount_value is not None and not isinstance(discount_value, (int, float)):
        _log("error", "VALIDATION_ERROR", "discount_value must be a number", account=account_id)
        return _err("VALIDATION_ERROR", "discount_value must be a number", field="discount_value")
    if isinstance(discount_value, bool):
        _log("error", "VALIDATION_ERROR", "discount_value must be a number", account=account_id)
        return _err("VALIDATION_ERROR", "discount_value must be a number", field="discount_value")
    if discount_value is not None and discount_value < 0:
        _log("error", "VALIDATION_ERROR", "discount_value must be >= 0", account=account_id)
        return _err("VALIDATION_ERROR", "discount_value must be >= 0", field="discount_value")

    currency = body.get("currency", None)
    allowed_currency = ["USD", "EUR", "GBP", "CAD", "AUD", "NZD", "JPY", "CHF", "SEK", "NOK", "DKK"]
    if currency is not None and currency not in allowed_currency:
        _log("error", "VALIDATION_ERROR", "Unsupported currency", account=account_id)
        return _err("VALIDATION_ERROR", "Unsupported currency", field="currency")
    if discount_type == "fixed":
        if currency is None:
            _log("error", "VALIDATION_ERROR", "currency is required for fixed discounts", account=account_id)
            return _err("VALIDATION_ERROR", "currency is required for fixed discounts", field="currency")

    max_redemptions = body.get("max_redemptions", None)
    if max_redemptions is not None:
        if not isinstance(max_redemptions, int) or isinstance(max_redemptions, bool) or max_redemptions < 1:
            _log("error", "VALIDATION_ERROR", "max_redemptions must be an integer >= 1", account=account_id)
            return _err("VALIDATION_ERROR", "max_redemptions must be an integer >= 1", field="max_redemptions")

    max_redemptions_per_profile = body.get("max_redemptions_per_profile", None)
    if max_redemptions_per_profile is not None:
        if not isinstance(max_redemptions_per_profile, int) or isinstance(max_redemptions_per_profile, bool) or max_redemptions_per_profile < 1:
            _log("error", "VALIDATION_ERROR", "max_redemptions_per_profile must be an integer >= 1", account=account_id)
            return _err("VALIDATION_ERROR", "max_redemptions_per_profile must be an integer >= 1", field="max_redemptions_per_profile")

    minimum_subtotal = body.get("minimum_subtotal", None)
    if minimum_subtotal is not None:
        if not isinstance(minimum_subtotal, (int, float)) or isinstance(minimum_subtotal, bool):
            _log("error", "VALIDATION_ERROR", "minimum_subtotal must be a number", account=account_id)
            return _err("VALIDATION_ERROR", "minimum_subtotal must be a number", field="minimum_subtotal")
        if minimum_subtotal < 0:
            _log("error", "VALIDATION_ERROR", "minimum_subtotal must be >= 0", account=account_id)
            return _err("VALIDATION_ERROR", "minimum_subtotal must be >= 0", field="minimum_subtotal")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)

    starts_dt, e = _parse_dt(body.get("starts_at"), "starts_at")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"], account=account_id)
        return e
    ends_dt, e = _parse_dt(body.get("ends_at"), "ends_at")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"], account=account_id)
        return e
    if starts_dt and ends_dt and ends_dt < starts_dt:
        _log("error", "VALIDATION_ERROR", "ends_at cannot be earlier than starts_at", account=account_id)
        return _err("VALIDATION_ERROR", "ends_at cannot be earlier than starts_at", field="ends_at")

    metadata = body.get("metadata", None)
    if metadata is not None and not isinstance(metadata, dict):
        _log("error", "VALIDATION_ERROR", "metadata must be an object", account=account_id)
        return _err("VALIDATION_ERROR", "metadata must be an object", field="metadata")

    resources = _load("resources.json")
    # Uniqueness: unique(account_id, external_key) where resource_type='coupon'
    for r in resources:
        if r.get("account_id") == account_id and r.get("resource_type") == "coupon" and r.get("external_key") == code_norm:
            _log("error", "CONFLICT", "Coupon code already exists", account=account_id, resource_id=r.get("id"))
            return _err("CONFLICT", "Coupon code already exists", field="code", existing_id=r.get("id"))

    # Create new coupon resource
    new_id = "klv_res_" + hashlib.sha1(f"coupon:{account_id}:{time.time_ns()}".encode()).hexdigest()[:12].upper()
    coupon_body = {}
    # Preserve known fields in coupon body for downstream usage
    for k in ["name", "description", "starts_at", "ends_at", "discount_type", "discount_value", "currency",
              "max_redemptions", "max_redemptions_per_profile", "minimum_subtotal", "metadata", "external_key", "code"]:
        if k in body:
            coupon_body[k] = body.get(k)

    row = {
        "id": new_id,
        "account_id": account_id,
        "resource_type": "coupon",
        "external_key": code_norm,  # canonical coupon code in resource row per constraints
        "name": body.get("name"),
        "status": status,
        "parent_id": None,
        "profile_id": None,
        "audience_id": None,
        "tag_id": None,
        "target_resource_id": None,
        "target_resource_type": None,
        "body": coupon_body,
        "analytics": None,
        "created_at": now,
        "updated_at": now
    }
    resources.append(row)
    _save("resources.json", resources)

    _log("ok", account=account_id, resource_id=new_id)
    return {"data": row}

