def get_product_review(product_review_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0246000" if __import__("os").path.isdir("./environment_mix/0246000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, account_id=None, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "klv_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "method": "GET",
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _enforce_limits(credential_id, account_id, endpoint):
        # Very small but real enforcement using request_logs.json
        # - RATE_LIMIT: > 120 requests in last 60s per credential OR per account if no credential
        # - QUOTA_EXCEEDED: > 50,000 requests in last 30d per account
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        win_rate_start = now_dt - datetime.timedelta(seconds=60)
        win_quota_start = now_dt - datetime.timedelta(days=30)

        rate_count = 0
        quota_count = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                ts2 = ts.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(ts2)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue

            if account_id and r.get("account_id") == account_id and dt >= win_quota_start:
                quota_count += 1

            # rate scoped to credential if present else to account
            if dt >= win_rate_start:
                if credential_id:
                    if r.get("credential_id") == credential_id:
                        rate_count += 1
                else:
                    if account_id and r.get("account_id") == account_id:
                        rate_count += 1

        if quota_count >= 50000:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", account_id=account_id, endpoint=endpoint)
        if rate_count >= 120:
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", account_id=account_id, endpoint=endpoint)
        return None

    def _resolve_identity_best_effort():
        # No explicit credential parameter for this endpoint: try to find an active account context.
        # Prefer accounts.status='active' that actually has product_review resources to serve the call.
        accounts = _load("accounts.json")
        resources = _load("resources.json")
        if not isinstance(accounts, list) or not isinstance(resources, list):
            return None
        # First try accounts that have product_review resources
        acct_ids_with_reviews = set()
        for r in resources:
            if isinstance(r, dict) and r.get("resource_type") == "product_review":
                aid = r.get("account_id")
                if isinstance(aid, str):
                    acct_ids_with_reviews.add(aid)
        # Active accounts first
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            aid = a.get("id")
            if isinstance(aid, str) and (aid in acct_ids_with_reviews or not acct_ids_with_reviews):
                return {"account": a, "credential": None}
        # Any non-closed account
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("status") == "closed":
                continue
            return {"account": a, "credential": None}
        return None

    endpoint = "get_product_review"

    # Validate input
    if not isinstance(product_review_id, str):
        _log(400, endpoint, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "product_review_id must be a string.")
    if not re.match(r"^klv_res_[0-9A-Z]{4,}$", product_review_id):
        _log(400, endpoint, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "product_review_id is not in the expected format.", field="product_review_id")

    ident = _resolve_identity_best_effort()
    if not ident:
        _log(401, endpoint, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized account context available.")
    account = ident["account"]
