        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        win_rate_start = now_dt - datetime.timedelta(seconds=60)
        win_quota_start = now_dt - datetime.timedelta(days=30)

        rate_count = 0
        quota_count = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                ts2 = ts.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(ts2)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue

            if account_id and r.get("account_id") == account_id and dt >= win_quota_start:
                quota_count += 1

            if dt >= win_rate_start:
                if credential_id:
                    if r.get("credential_id") == credential_id:
                        rate_count += 1
                else:
                    if account_id and r.get("account_id") == account_id:
                        rate_count += 1

        if quota_count >= 50000:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", account_id=account_id, endpoint=endpoint)
        if rate_count >= 120:
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", account_id=account_id, endpoint=endpoint)
        return None

    endpoint = "get_images"

    # Validate account_id
    if not isinstance(account_id, str):
        _log(400, endpoint, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a string.")
