        _log(400, endpoint, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is not in the expected format.", field="account_id")

    allowed_status = {"draft","active","paused","archived","deleted","enabled","disabled","pending","fulfilled","failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status filter.", field="status", allowed=sorted(list(allowed_status)))

    if external_key is not None and not isinstance(external_key, str):
        _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
