    if not isinstance(limit, int):
        _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1-200).", field="limit")

    allowed_sort = {"created_at","-created_at","updated_at","-updated_at","name","-name"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort.", field="sort", allowed=sorted(list(allowed_sort)))

    # Account must exist
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(500, endpoint, account_id=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account store not available.")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct:
        _log(404, endpoint, account_id=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    limerr = _enforce_limits(None, account_id, endpoint)
    if limerr:
        _log(429 if limerr["error"]["code"] == "RATE_LIMIT" else 403, endpoint, account_id=account_id, error_code=limerr["error"]["code"])
        return limerr

    # Cursor parsing
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
        except Exception:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("endpoint") != endpoint:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor payload.", field="cursor")
        if payload.get("account_id") != account_id or payload.get("status") != status or payload.get("external_key") != external_key or payload.get("sort") != sort:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match the current query.", field="cursor")
        if not isinstance(payload.get("start"), int) or payload["start"] < 0:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor position.", field="cursor")
        # expiry: 15 minutes
        try:
            issued = datetime.datetime.fromisoformat(payload["issued_at"].replace("Z", "+00:00"))
            if issued.tzinfo is not None:
                issued = issued.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor timestamp.", field="cursor")
        if datetime.datetime.utcnow() - issued > datetime.timedelta(minutes=15):
            _log(400, endpoint, account_id=account_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor expired.", field="cursor")
        start = payload["start"]

    resources = _load("resources.json")
    if not isinstance(resources, list):
        _log(500, endpoint, account_id=account_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Resource store not available.")

    # Filter
    rows = []
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        if r.get("resource_type") != "image":
            continue
        if status is not None and r.get("status") != status:
            continue
        if external_key is not None and r.get("external_key") != external_key:
            continue
        rows.append(r)

    # Sort
    reverse = False
    key = sort
    if sort.startswith("-"):
        reverse = True
        key = sort[1:]

    def _sort_key(d):
        v = d.get(key)
        if v is None:
            # None sorts last for asc, first for desc: normalize by tuple
            return (1, "")
        return (0, v if isinstance(v, str) else str(v))

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        payload = {
            "v": 1,
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "external_key": external_key,
            "sort": sort,
            "start": start + limit,
            "issued_at": now
        }
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8")

    _log(200, endpoint, account_id=account_id)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

