                "scopes": credential_row.get("scopes") if isinstance(credential_row.get("scopes"), list) else ["read:*"],
                "status": credential_row.get("status", "active"),
                "synthetic": bool(credential_row.get("synthetic", False))
            },
            "account": account_row,
            "limits": {
                "rate_limit": {"window_seconds": 60, "limit": rate_limit, "used": rate_used, "remaining": max(0, rate_limit - rate_used)},
                "quota": {"window_days": 30, "limit": quota_limit, "used": quota_used, "remaining": max(0, quota_limit - quota_used)}
            }
        }
    }
